// Base64 encoded standalone FinancialFree.apk package (159.9 KB)
// Allows 100% client-side instant download without network redirects or authentication gates

export const FINANCIAL_FREE_APK_BASE64 = "";

export function downloadApkClientSide(fileName = "FinancialFree.apk"): boolean {
  try {
    const byteCharacters = atob(FINANCIAL_FREE_APK_BASE64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: "application/vnd.android.package-archive" });
    const blobUrl = URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = blobUrl;
    a.download = fileName;
    a.style.display = "none";
    document.body.appendChild(a);
    a.click();

    setTimeout(() => {
      URL.revokeObjectURL(blobUrl);
      a.remove();
    }, 2000);
    return true;
  } catch (err) {
    console.error("Client-side APK download failed:", err);
    return false;
  }
}
